frappe.ui.form.on("Lead", {
    refresh(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button("Create Freight Quotation", () => {
                frappe.call({
                    method: "freight_forwarder.lead_to_quotation.create_quotation_from_lead",
                    args: {
                        lead_name: frm.doc.name
                    },
                    freeze: true,
                    callback: function (r) {
                        if (r.message) {
                            frappe.set_route("Form", "Freight Quotation", r.message);
                        }
                    }
                });
            });
        }
    }
});

frappe.ui.form.on("Purchase Invoice", {
    refresh(frm) {
        if (frm.doc.docstatus === 1) { // Only show button for submitted invoices
            frm.add_custom_button("Download PDF", () => {
                const print_format = "Standard"; // Change if you have a custom print format

                const url = `/printview?doctype=Purchase Invoice`
                    + `&name=${frm.doc.name}`
                    + `&format=${print_format}`
                    + `&no_letterhead=0`
                    + `&trigger_print=1`
                    + `&letterhead=Default`;

                window.open(url, "_blank"); // Opens PDF in a new tab
            });
        }
    }
});

