frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        // Add button to go back to Freight Job if linked
        if (frm.doc.freight_job) {
            frm.add_custom_button("Go to Freight Job", () => {
                frappe.set_route("Form", "Freight Job", frm.doc.freight_job);
            });
        }
    }
});

frappe.ui.form.on('Freight Quotation Charge', {
    qty: recalc,
    rate: recalc,
    billable_to: recalc
});

function recalc(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    row.amount = flt(row.qty) * flt(row.rate);
    frm.refresh_field('charges');

    let total = 0;
    (frm.doc.charges || []).forEach(r => {
        if (r.billable_to === "Customer") {
            total += flt(r.amount);
        }
    });

    frm.set_value('total_sell', total);
}

frappe.ui.form.on("Payment Entry", {
    refresh(frm) {
        // Do not show button on unsaved documents
        if (frm.is_new()) return;

        // Optional: show only after submission
        if (frm.doc.docstatus !== 1) return;

        frm.add_custom_button("Download PDF", () => {
            const print_format = "Standard"; // or your custom Payment Entry print format

            const url =
                `/printview?doctype=Payment Entry` +
                `&name=${encodeURIComponent(frm.doc.name)}` +
                `&format=${encodeURIComponent(print_format)}` +
                `&no_letterhead=0` +
                `&trigger_print=1`;

            window.open(url, "_blank");
        });
    }
});

frappe.ui.form.on('Payment Entry', {
    refresh(frm) {
        // Show button only if linked Freight Job exists
        if (frm.doc.freight_job) {
            frm.add_custom_button('Go to Freight Job', () => {
                frappe.set_route("Form", "Freight Job", frm.doc.freight_job);
            });
        }
    }
});

frappe.ui.form.on('Freight Job', {
    refresh: function(frm) {
        // Show Activate button only for Draft jobs not activated
        if (!frm.doc.__islocal && !frm.doc.activated && frm.doc.docstatus === 0) {
            frm.add_custom_button(__('Activate Job'), function() {
                frappe.confirm(
                    'Are you sure you want to Activate this Freight Job?',
                    function() {
                        frappe.call({
                            method: "freight_forwarder.freight_forwarder.doctype.freight_job.freight_job.activate",
                            args: {
                                name: frm.doc.name
                            },
                            callback: function(r) {
                                if (!r.exc) {
                                    frm.reload_doc();
                                }
                            }
                        });
                    }
                );
            }, __('Actions'));
        }
    }
});

frappe.ui.form.on('Freight Job', {
    refresh(frm) {

        // -----------------------------
        // Create Job Cost Sheet
        // -----------------------------
        frm.add_custom_button(__('Create Job Cost Sheet'), () => {
            frappe.new_doc('Job Cost Sheet', { job: frm.doc.name });
        });
        if (frm.doc.job_cost_sheet_created) {
            frm.get_field('Create Job Cost Sheet').$wrapper.find('button')
                .attr('title', 'Job Cost Sheet already created.');
        }

        // -----------------------------
        // Create Sales Invoice
        // -----------------------------
        frm.add_custom_button(__('Create Sales Invoice'), async () => {
            const r = await frappe.call({
                method: "freight_forwarder.sales_invoice.create_sales_invoice",
                args: { freight_job: frm.doc.name }
            });
            if (r.message) {
                frappe.msgprint(`Sales Invoice ${r.message} created`);
                frappe.set_route("Form", "Sales Invoice", r.message);
            }
        });
        if (frm.doc.sales_invoice_created) {
            frm.get_field('Create Sales Invoice').$wrapper.find('button')
                .attr('title', 'Sales Invoice already created.');
        }



        // -----------------------------
        // Receive Payment
        // -----------------------------
        frm.add_custom_button(__('Receive Payment'), async () => {
            const r = await frappe.call({
                method: "freight_forwarder.payment_entry.create_receive_payment",
                args: { freight_job: frm.doc.name }
            });
            if (r.message) {
                frappe.msgprint("Payment Entry Created: " + r.message);
                frappe.set_route("Form", "Payment Entry", r.message);
            }
        });
        if (frm.doc.docstatus === 0) {
            frm.get_field('Receive Payment').$wrapper.find('button')
                .attr('title', 'You can receive payment even in Draft. Submission requires all validations.');
        }

    }
});

