frappe.ui.form.on('Booking', {
    refresh: function(frm) {
        // Show button only if Booking is Confirmed and Freight Job not created
        if(frm.doc.status == "Confirmed" && !frm.doc.freight_job_created) {
            frm.add_custom_button(__('Create Freight Job'), function() {
                frappe.call({
                    method: "freight_forwarder.booking.create_freight_job",
                    args: { booking_name: frm.doc.name },
                    callback: function(r) {
                        if(r.message) {
                            frm.set_value('freight_job_created', 1);
                            frappe.msgprint(__('Freight Job {0} created', [r.message]));
                            frm.reload_doc();
                        }
                    }
                });
            });
        }
    }
});

