frappe.ui.form.on('Job Cost Sheet', {
    refresh(frm) {
        calculate_total(frm);
    },
    cost_items_add(frm) {
        calculate_total(frm);
    },
    cost_items_remove(frm) {
        calculate_total(frm);
    }
});

frappe.ui.form.on('Job Cost Item', {
    amount(frm) {
        calculate_total(frm);
    }
});

function calculate_total(frm) {
    let total = 0;
    (frm.doc.cost_items || []).forEach(row => {
        total += flt(row.amount);
    });
    frm.set_value('total_cost', total);
}

frappe.ui.form.on('Job Cost Sheet', {
    refresh(frm) {
        if (frm.doc.docstatus === 1 && !frm.doc.purchase_invoice_created) {
            frm.add_custom_button(__('Create Purchase Invoice'), async () => {
                try {
                    let r = await frappe.call({
                        method: "freight_forwarder.purchase_invoice.create_purchase_invoice",
                        args: {
                            job_cost_sheet: frm.doc.name
                        }
                    });

                    if (r.message) {
                        // Show message from server
                        frappe.msgprint(r.message.message);

                        // Open each created invoice (optional)
                        if (r.message.invoices && r.message.invoices.length > 0) {
                            r.message.invoices.forEach(inv => {
                                frappe.set_route("Form", "Purchase Invoice", inv);
                            });
                        }

                        // Reload Job Cost Sheet to prevent stale doc error
                        frm.reload_doc();
                    }
                } catch (err) {
                    frappe.msgprint(__('Error creating Purchase Invoice: {0}', [err.message]));
                }
            });
        }
    }
});

